import { Diagram, Edge } from "diagrams-js";
import { Fargate, Lambda } from "diagrams-js/aws/compute";
import { Dynamodb, ElasticacheForRedis, RDSPostgresqlInstance } from "diagrams-js/aws/database";
import { SQS } from "diagrams-js/aws/integration";
import { ALB, CloudFront, Route53 } from "diagrams-js/aws/network";
import { S3 } from "diagrams-js/aws/storage";
import { Users } from "diagrams-js/onprem/client";

const diagram = Diagram("shop (Terraform)", { direction: "LR", theme: "neutral", curvestyle: "ortho" });

const users = diagram.add(Users("Users"));
const dns = diagram.add(Route53("example.com"));
const cdn = diagram.add(CloudFront("cdn"));
const assets = diagram.add(S3("shop-assets"));

const vpc = diagram.cluster("VPC shop (module)");
const pub = vpc.cluster("public subnets");
const alb = pub.add(ALB("shop-web"));
const priv = vpc.cluster("private subnets");
const ecs = priv.cluster("ECS shop");
const web = ecs.add(Fargate("web ×2"));
const db = priv.add(RDSPostgresqlInstance("shop (postgres)"));
const cache = priv.add(ElasticacheForRedis("shop-cache"));

const orders = diagram.add(SQS("shop-orders"));
const dlq = diagram.add(SQS("shop-orders-dlq"));
const fulfil = diagram.add(Lambda("shop-fulfil"));
const shipments = diagram.add(Dynamodb("shop-shipments"));

users.to(dns).to(cdn);
cdn.to(Edge({ label: "assets" }), assets);
cdn.to(Edge({ label: "web" }), alb);
alb.to(Edge({ label: ":3000" }), web);
web.to(Edge({ label: ":5432" }), db);
web.to(cache);
web.to([assets, orders]);
orders.to(Edge({ style: "dashed", label: "redrive" }), dlq);
orders.to(Edge({ label: "poll" }), fulfil);
fulfil.to(shipments);

export default diagram;
